@Service
public class OrderService {
    private final OrderRepository orders; private final StockGateway stock;
    OrderService(OrderRepository orders, StockGateway stock) { this.orders = orders; this.stock = stock; }

    @Transactional                       // proxied: begin before, commit/rollback after
    public OrderId place(OrderRequest req) {
        Order order = orders.insert(Order.create(req));
        stock.reserve(order.id());
        return order.id();
    }
}

@Stateless
public class OrderServiceBean {                // container-managed transaction
    @EJB OrderRepository orders;
    @EJB StockGateway stock;

    public OrderId place(OrderRequest req) {   // REQUIRED by default
        Order order = orders.insert(Order.create(req));
        stock.reserve(order.id());
        return order.id();
    }
}

public class OrderService {                      // no container
    private final DataSource ds;

    public OrderId place(OrderRequest req) throws SQLException {
        try (Connection c = ds.getConnection()) {
            c.setAutoCommit(false);
            try { OrderId id = insertOrder(c, req); reserveStock(c, id); c.commit(); return id; }
            catch (SQLException e) { c.rollback(); throw e; }
        }
    }
}

